import{_ as a,o as e,c as n,a5 as r}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"uni-app Vue 在鸿蒙上如何运行？编译、运行时与原生能力","description":"不是鸿蒙直接认识 Vue，而是 uni-app 编译打包 + 运行时适配；普通页面走 JSVM/ArkWeb，原生能力走 UTS；高频图表场景宜做页面级原生页。","frontmatter":{"title":"uni-app Vue 在鸿蒙上如何运行？编译、运行时与原生能力","date":"2026-05-19T00:00:00.000Z","tags":["uni-app","Vue","鸿蒙","HarmonyOS","UTS","uni-app x"],"categories":["移动开发"],"description":"不是鸿蒙直接认识 Vue，而是 uni-app 编译打包 + 运行时适配；普通页面走 JSVM/ArkWeb，原生能力走 UTS；高频图表场景宜做页面级原生页。"},"headers":[],"relativePath":"posts/移动开发/uni-app/uni-app Vue 在鸿蒙上如何运行？编译、运行时与原生能力.md","filePath":"posts/移动开发/uni-app/uni-app Vue 在鸿蒙上如何运行？编译、运行时与原生能力.md","lastUpdated":1790163617000}'),p={name:"posts/移动开发/uni-app/uni-app Vue 在鸿蒙上如何运行？编译、运行时与原生能力.md"};function o(i,t,u,l,s,d){return e(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="uni-app-vue-在鸿蒙上如何运行-编译、运行时与原生能力" tabindex="-1">uni-app Vue 在鸿蒙上如何运行？编译、运行时与原生能力 <a class="header-anchor" href="#uni-app-vue-在鸿蒙上如何运行-编译、运行时与原生能力" aria-label="Permalink to &quot;uni-app Vue 在鸿蒙上如何运行？编译、运行时与原生能力&quot;">​</a></h1><p><strong>一句话</strong>：不是鸿蒙「直接认识 Vue」，而是 <strong>uni-app 把 Vue 页面编译、打包进鸿蒙应用，并带上自己的运行时适配层</strong>。</p><p>本文是 uni-app 鸿蒙端运行原理说明，与 <a href="/blog/posts/移动开发/uni-app/移动端打包签名与 DCloud 离线打包教程">移动端打包签名与 DCloud 离线打包教程</a>（构建与签名流程）互补。</p><hr><h2 id="一、三层结构" tabindex="-1">一、三层结构 <a class="header-anchor" href="#一、三层结构" aria-label="Permalink to &quot;一、三层结构&quot;">​</a></h2><p>原理可以理解成三层：</p><h3 id="_1-源码层" tabindex="-1">1. 源码层 <a class="header-anchor" href="#_1-源码层" aria-label="Permalink to &quot;1. 源码层&quot;">​</a></h3><p>你写的是 <code>.vue</code>：<code>template + script + style</code>。</p><p>里面的 <code>view</code>、<code>button</code>、<code>scroll-view</code>、<code>uni.request</code> 等 <strong>不是纯浏览器 API</strong>，而是 uni-app 的跨端抽象——同一套写法面向小程序、App、H5、鸿蒙等多端。</p><h3 id="_2-编译和打包层" tabindex="-1">2. 编译和打包层 <a class="header-anchor" href="#_2-编译和打包层" aria-label="Permalink to &quot;2. 编译和打包层&quot;">​</a></h3><p>HBuilderX 会把项目编译成鸿蒙目标产物，并生成/合并到鸿蒙工程目录，例如：</p><ul><li><code>unpackage/dist/dev/app-harmony</code></li><li><code>unpackage/dist/build/app-harmony</code></li></ul><p>再调用 DevEco / HarmonyOS 工具链完成构建、签名、安装。</p><p>DCloud 官方文档说明：HBuilderX <strong>4.24+</strong> 开始支持运行到鸿蒙平台，并会调用鸿蒙工具链完成构建安装。</p><ul><li><a href="https://uniapp.dcloud.net.cn/tutorial/harmony/runbuild.html" target="_blank" rel="noreferrer">运行到鸿蒙平台</a></li></ul><h3 id="_3-运行时层" tabindex="-1">3. 运行时层 <a class="header-anchor" href="#_3-运行时层" aria-label="Permalink to &quot;3. 运行时层&quot;">​</a></h3><p>普通 uni-app Vue 页面在鸿蒙里主要靠 <strong>JSVM + Web/ArkWeb 渲染环境 + uni 运行时</strong> 跑起来：</p><table tabindex="0"><thead><tr><th>层次</th><th>作用</th></tr></thead><tbody><tr><td>Vue 逻辑</td><td>运行在 JS 环境里</td></tr><tr><td>页面渲染</td><td>通过鸿蒙的 Web 能力（ArkWeb）承载</td></tr><tr><td>uni 运行时</td><td>负责组件、路由、生命周期、API 适配</td></tr><tr><td>鸿蒙原生能力</td><td>普通 JS 不能直接调 <code>@kit</code>，需通过 <strong>UTS 插件</strong>；UTS 编译成 ArkTS/ETS 调用鸿蒙原生 API</td></tr></tbody></table><p>参考：</p><ul><li><a href="https://uniapp.dcloud.net.cn/tutorial/harmony/history.html" target="_blank" rel="noreferrer">鸿蒙平台开发历史与架构</a></li><li><a href="https://uniapp.dcloud.net.cn/plugin/uts-for-harmony.html" target="_blank" rel="noreferrer">UTS 插件开发（鸿蒙）</a></li></ul><hr><h2 id="二、整体链路" tabindex="-1">二、整体链路 <a class="header-anchor" href="#二、整体链路" aria-label="Permalink to &quot;二、整体链路&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vue 页面</span></span>
<span class="line"><span>  ↓ uni 编译器</span></span>
<span class="line"><span>JS / CSS / 资源 + uni 运行时</span></span>
<span class="line"><span>  ↓ HBuilderX + DevEco 工具链</span></span>
<span class="line"><span>鸿蒙 HAP 应用</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>鸿蒙 JSVM / ArkWeb / ArkTS 插件能力</span></span></code></pre></div><hr><h2 id="三、关键区别-普通-uni-app-arkui-原生页" tabindex="-1">三、关键区别：普通 uni-app ≠ ArkUI 原生页 <a class="header-anchor" href="#三、关键区别-普通-uni-app-arkui-原生页" aria-label="Permalink to &quot;三、关键区别：普通 uni-app ≠ ArkUI 原生页&quot;">​</a></h2><p>要注意：<strong>普通 uni-app 页面不是等价于鸿蒙 ArkUI 原生页面</strong>。</p><p>DCloud 文档也提到：</p><ul><li>鸿蒙端 <strong>只支持 Vue 3</strong></li><li><code>nvue</code> 到鸿蒙后 <strong>也不是原生渲染</strong>，而是类似 Web 渲染</li></ul><p>详见 <a href="https://uniapp.dcloud.net.cn/tutorial/harmony/runbuild.html" target="_blank" rel="noreferrer">运行到鸿蒙平台</a>。</p><hr><h2 id="四、uni-app-x-uvue-更偏原生的一条路" tabindex="-1">四、uni-app x / uvue：更偏原生的一条路 <a class="header-anchor" href="#四、uni-app-x-uvue-更偏原生的一条路" aria-label="Permalink to &quot;四、uni-app x / uvue：更偏原生的一条路&quot;">​</a></h2><p>如果是 <strong>uni-app x / uvue</strong>，路线又更「原生」一些。</p><p>DCloud 的说法是：uvue 渲染引擎包含 UTS 版 Vue 框架、跨平台基础 UI 和 CSS 引擎，可以把 Vue 语法页面 <strong>编译成不同平台的高性能原生界面</strong>。</p><ul><li><a href="https://doc.dcloud.net.cn/uni-app-x/" target="_blank" rel="noreferrer">uni-app x 文档</a></li></ul><p>与普通 uni-app 对比：</p><table tabindex="0"><thead><tr><th>维度</th><th>普通 uni-app（Vue）</th><th>uni-app x（uvue）</th></tr></thead><tbody><tr><td>鸿蒙渲染</td><td>Web/ArkWeb 为主</td><td>更偏原生 UI 编译</td></tr><tr><td>性能敏感 UI</td><td>受 Web 层限制</td><td>更适合高性能原生界面</td></tr><tr><td>学习/迁移成本</td><td>现有 Vue 项目可直接跑</td><td>需按 uvue 规范改造</td></tr></tbody></table><hr><h2 id="五、放到图表项目里的结论" tabindex="-1">五、放到图表项目里的结论 <a class="header-anchor" href="#五、放到图表项目里的结论" aria-label="Permalink to &quot;五、放到图表项目里的结论&quot;">​</a></h2><p>结合 <strong>futures-uniapp-client</strong> 这类行情/图表项目，实践建议是：</p><table tabindex="0"><thead><tr><th>场景</th><th>建议</th></tr></thead><tbody><tr><td>普通业务页（列表、表单、设置、登录）</td><td>用 uni Vue 跑鸿蒙 <strong>没问题</strong></td></tr><tr><td>高频图表、十字光标、缩放拖拽、实时 K 线</td><td><strong>不应让 Uni 层持续驱动</strong>；宜做 <strong>页面级原生行情详情页</strong></td></tr></tbody></table><p>这也符合当前项目规则：</p><ul><li><strong>UniApp 只做页面入口</strong></li><li><strong>不做图表级持续桥接</strong>（避免 JS ↔ 原生高频通信成为性能瓶颈）</li></ul><p>原生行情页由鸿蒙侧（ArkUI + 自绘/原生图表引擎）承载交互与刷新；Uni 层只负责路由跳转、参数传递、返回列表等「入口级」职责。</p><hr><h2 id="六、一句话总结" tabindex="-1">六、一句话总结 <a class="header-anchor" href="#六、一句话总结" aria-label="Permalink to &quot;六、一句话总结&quot;">​</a></h2><p><strong>鸿蒙不认识 Vue 语法本身，认识的是 uni-app 编译出的 HAP + 运行时。</strong><br><strong>普通页 = JSVM + ArkWeb + uni 适配；要 <code>@kit</code> 原生能力 = UTS 插件。</strong><br><strong>图表/K 线这类重交互页，入口用 Uni，渲染与驱动用原生。</strong></p><hr><p><strong>系列导航</strong></p><ul><li><a href="/blog/posts/移动开发/uni-app/移动端打包签名与 DCloud 离线打包教程">移动端打包签名与 DCloud 离线打包教程（系列总览）</a></li><li><a href="/blog/posts/移动开发/uni-app/SHA1 是什么？Android、iOS 与鸿蒙签名发证有何不同">SHA1 与三平台发证差异</a></li><li><a href="/blog/posts/移动开发/uni-app/DCloud AppKey 是什么？离线打包三要素必须一致">DCloud AppKey 是什么？</a></li></ul>`,49)])])}const b=a(p,[["render",o]]);export{c as __pageData,b as default};
